Let $A = \begin{pmatrix} \sec^2 x & 1 & 1 \\ \cos^2 x & \cos^2 x & \csc^2 x \\ 1 & \cos^2 x & \cot^2 x \end{pmatrix}$.
We want to find the determinant of $A$.
\begin{align*} \det(A) &= \sec^2 x \begin{vmatrix} \cos^2 x & \csc^2 x \\ \cos^2 x & \cot^2 x \end{vmatrix} - 1 \begin{vmatrix} \cos^2 x & \csc^2 x \\ 1 & \cot^2 x \end{vmatrix} + 1 \begin{vmatrix} \cos^2 x & \cos^2 x \\ 1 & \cos^2 x \end{vmatrix} \\ &= \sec^2 x (\cos^2 x \cot^2 x - \csc^2 x \cos^2 x) - 1 (\cos^2 x \cot^2 x - \csc^2 x) + 1 (\cos^4 x - \cos^2 x) \\ &= \sec^2 x \cos^2 x (\cot^2 x - \csc^2 x) - \cos^2 x \cot^2 x + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \sec^2 x \cos^2 x \left( \frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x} \right) - \cos^2 x \frac{\cos^2 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \sec^2 x \cos^2 x \left( \frac{\cos^2 x - 1}{\sin^2 x} \right) - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\sec^2 x \cos^2 x (\cos^2 x - 1)}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\frac{1}{\cos^2 x} \cos^2 x (\cos^2 x - 1)}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{1 (\cos^2 x - 1)}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x - 1}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x - 1 - \cos^4 x + 1 + \sin^2 x \cos^4 x - \sin^2 x \cos^2 x}{\sin^2 x} \\ &= \frac{\cos^2 x - 1 - \cos^4 x + 1 + \cos^4 x - \cos^2 x}{\sin^2 x} \\ &= \frac{0}{\sin^2 x} \\ &= 0 \end{align*}

\boxed{0}
