\begin{align*} \label{eq:1}
\text{Volume of the original cube} &= 2 \times 2 \times 2 = 8 \text{ cubic centimeters} \\
\text{Increased volume} &= 8 + 19 = 27 \text{ cubic centimeters} \\
\text{Let } x \text{ be the length of one edge of the new cube} \\
\text{Volume of the new cube} &= x^3 \\
\text{Therefore} x^3 &= 27 \\
x &= \sqrt[3]{27} \\
x &= 3 \text{ centimeters}
\end{align*}
